<script lang="ts">
 import { onMount } from 'svelte';
 import { invoke } from '@tauri-apps/api/core';
 import { emptyLedger, totals, categorySuggestion, recurringSuggestions } from './lib/model';
 import type { Ledger, Transaction, Kind, ImportReport } from './lib/model';
 import { inspectWorkbook, planImport } from './lib/importer';
 import { yen, calculate } from './lib/arithmetic';
 import ReceiptScanner from './components/ReceiptScanner.svelte';
 import type { ReceiptDraft } from './lib/receipts';
 import TagSelector from './components/TagSelector.svelte';
 import { tagNames,resolveTagNames,matchesTags,tagSpending,bulkTags,renameTag,removeTag,ensureTag } from './lib/tags';
 import { tagKey } from './lib/tag-names';
 import { csvText as exportRows } from './lib/csv';
 let scannerOpen=false;
 async function saveReceipt(d:ReceiptDraft){
  if(busy)throw new Error('Another save is in progress. Wait and retry.');
  const resolved=resolveTagNames(structuredClone(ledger),d.tagNames),flags:string[]=[];
  if(d.amount===null)flags.push('Missing amount');if(!d.date)flags.push('Undated');if(d.date&&d.date.slice(0,7)!==d.month)flags.push('Date outside reporting month');
  const t:Transaction={id:crypto.randomUUID(),date:d.date,month:d.month,description:d.description,amount:d.amount,type:d.type,category:d.category,tagIds:resolved.ids,notes:'',flags,expression:d.expression,receipt:{origin:'receipt-scan',input:d.via,engine:'tesseract.js-6.0.1',reviewedAt:new Date().toISOString()}};
  resolved.ledger.transactions.push(t);await commit(resolved.ledger,'Reviewed receipt saved');month=d.month;view='month';
 }
 const native=!!(window as any).__TAURI_INTERNALS__;
 const localDay=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
 let ledger:Ledger=emptyLedger(), loaded=false,busy=false,error='',status='',path='',recovery='';
 let view:'month'|'history'|'tags'|'import'|'backups'='month';let month=localDay().slice(0,7),search='',kind='',categoryFilter='',flagged=false;
 let date=localDay(),description='',amount='',type:Kind='expense',category='',entryTags:string[]=[],notes='',entryMonth=month,editing:string|null=null;
 let filterTags:string[]=[],tagMode:'any'|'all'='any',selectedIds:string[]=[],bulkNames:string[]=[],tagIdToManage='',renameName='',newTagName='',confirmTagRemoval=false,mergeTagsConfirmed=false;
 let dateInput:HTMLInputElement,descInput:HTMLInputElement,fileInput:HTMLInputElement;
 let undoStack:Ledger[]=[];let pending:{transactions:Transaction[];report:ImportReport}|null=null;
 let previewSearch='',previewFilter='flagged';let backupNames:string[]=[],restoreName='',confirmRestore=false;
 let settings:any={schemaVersion:1,currency:'JPY',rounding:'half-away-from-zero',categories:['Food','Housing','Transport','Bills','Shopping','Entertainment','Travel','Health']};let settingsOpen=false,categoryText='';
 $: monthItems=ledger.transactions.filter(t=>t.month===month);
 $: summary=totals(monthItems);
 $: accumulated=totals(ledger.transactions.filter(t=>t.month<=month));
 $: months=[...new Set([month,...ledger.transactions.map(t=>t.month)])].sort().reverse();
 $: descriptions=[...new Set(ledger.transactions.map(t=>t.description))].sort();
 $: categories=[...new Set([...settings.categories,...ledger.transactions.map(t=>t.category).filter(Boolean)])].sort();
 $: filterTagIds=ledger.tags.filter(t=>filterTags.some(n=>tagKey(n)===tagKey(t.name))).map(t=>t.id);
 $: filtered=(view==='month'?monthItems:ledger.transactions).filter(t=>(!search||`${t.description} ${t.notes} ${t.source?.cell||''}`.toLowerCase().includes(search.toLowerCase()))&&(!kind||t.type===kind)&&(!categoryFilter||t.category===categoryFilter)&&matchesTags(t,filterTagIds,tagMode)&&(!flagged||t.flags.length||t.amount===null)).sort((a,b)=>b.month.localeCompare(a.month)||(b.date||'').localeCompare(a.date||''));
 $: filteredTotals=totals(filtered);
 $: spending=tagSpending(filtered);
 $: managedTag=ledger.tags.find(t=>t.id===tagIdToManage);
 $: renameCollision=ledger.tags.find(t=>t.id!==tagIdToManage&&tagKey(t.name)===tagKey(renameName));
 $: suggestions=recurringSuggestions(ledger.transactions,month);
 $: suggestion=categorySuggestion(description);
 $: plan=pending?planImport(ledger,pending.transactions):null;
 $: previewRows=pending?.transactions.filter(t=>(previewFilter==='all'||(previewFilter==='missing'?t.amount===null:previewFilter==='year'?t.flags.includes('Likely year error'):t.flags.length>0))&&`${t.description} ${t.source?.cell}`.toLowerCase().includes(previewSearch.toLowerCase()))||[];
 $: amountPreview=(()=>{try{return amount?`¥${fmt(yen(amount))}`:'';}catch{return 'Use numbers and + − * / ( )';}})();
 const fmt=(v:number)=>v.toLocaleString('en-US');const money=(v:number)=>`${v<0?'−':''}¥${fmt(Math.abs(v))}`;
 async function commit(next:Ledger,message:string,remember=true){if(busy)throw new Error('Another save is in progress');busy=true;error='';const before=structuredClone(ledger);try{const saved=native?await invoke<Ledger>('save',{ledger:next,expected:ledger.revision}):{...next,revision:ledger.revision+1};if(remember){undoStack=[...undoStack.slice(-29),before];}ledger=saved;selectedIds=selectedIds.filter(id=>saved.transactions.some(t=>t.id===id));filterTags=filterTags.filter(n=>saved.tags.some(t=>tagKey(t.name)===tagKey(n)));status=message+' · Saved';}catch(e){error=String(e);throw e;}finally{busy=false;}}
 async function undo(){if(!undoStack.length||busy)return;const old=undoStack.at(-1)!;try{await commit({...structuredClone(old),revision:ledger.revision},'Undone',false);undoStack=undoStack.slice(0,-1);}catch{}}
 function clearEntry(){editing=null;description='';amount='';category='';entryTags=[];notes='';type='expense';entryMonth=month;date=month===localDay().slice(0,7)?localDay():'';}
 async function submit(){if(!loaded||busy)return;error='';try{
  if(!description.trim())throw new Error('Enter a description');if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(entryMonth))throw new Error('Choose a reporting month');
  if(date&&(!/^\d{4}-\d{2}-\d{2}$/.test(date)||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date))throw new Error('Enter a valid date or leave it blank');
  const raw=amount.trim()?calculate(amount):null;let k=type;if(raw?.isNegative()&&type==='expense')k='income';if(raw?.isNegative()&&type!=='expense')throw new Error('Use a positive amount for the selected income type');
  const previous=editing?ledger.transactions.find(t=>t.id===editing):undefined;
  let flags=(previous?.flags||[]).filter(f=>!['Missing amount','Undated','Likely year error','Date outside reporting month','Rounded to whole yen'].includes(f));if(raw===null)flags.push('Missing amount');if(!date)flags.push('Undated');if(date&&date.slice(0,7)!==entryMonth)flags.push('Date outside reporting month');if(raw&&!raw.isInteger())flags.push('Rounded to whole yen');
  const resolved=resolveTagNames(structuredClone(ledger),entryTags);
  const t:Transaction={...previous,id:editing||crypto.randomUUID(),date:date||null,month:entryMonth,description:description.trim(),amount:raw===null?null:Math.abs(yen(amount)),type:k,category,tagIds:resolved.ids,notes,flags,expression:amount};
  const next=resolved.ledger;if(editing)next.transactions=next.transactions.map(x=>x.id===editing?t:x);else next.transactions.push(t);await commit(next,editing?'Entry updated':'Entry added');clearEntry();descInput?.focus();
 }catch(e){error=String(e instanceof Error?e.message:e);}}
 function edit(t:Transaction){if(view==='tags')view='history';editing=t.id;date=t.date||'';entryMonth=t.month;description=t.description;amount=t.amount===null?'':String(t.amount);type=t.type;category=t.category;entryTags=tagNames(ledger.tags,t.tagIds);notes=t.notes;descInput?.focus();}
 function duplicate(t?:Transaction){const last=t||ledger.transactions.at(-1);if(!last)return;edit(last);editing=null;date=month===localDay().slice(0,7)?localDay():'';entryMonth=month;status='Duplicated into the entry form. Press Enter to save.';}
 async function remove(t:Transaction){const next=structuredClone(ledger);next.transactions=next.transactions.filter(x=>x.id!==t.id);if(t.source&&!next.deletedSourceIds.includes(t.id))next.deletedSourceIds.push(t.id);try{await commit(next,'Entry deleted — Undo is available');if(editing===t.id)clearEntry();}catch{}}
 async function inspect(bytes:Uint8Array,name:string){busy=true;error='';status='Reading workbook…';try{pending=await inspectWorkbook(bytes,name);view='import';status='Preview ready. Nothing imported yet.';}catch(e){error=String(e);}finally{busy=false;}}
 async function pickFile(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(file)await inspect(new Uint8Array(await file.arrayBuffer()),file.name);(e.target as HTMLInputElement).value='';}
 async function bundled(){try{const r=await fetch('/Japan%20expenses.xlsx');if(!r.ok)throw new Error('Bundled workbook unavailable');await inspect(new Uint8Array(await r.arrayBuffer()),'Japan expenses.xlsx');}catch(e){error=String(e);}}
 async function importNow(){if(!pending||!plan)return;const next=structuredClone(ledger);next.transactions.push(...plan.fresh);if(!next.imports.some(r=>r.hash===pending!.report.hash))next.imports.push(pending.report);try{await commit(next,`Imported ${plan.fresh.length} entries; skipped ${plan.skipped.length}`);month=pending.report.months.at(-1)!.month;entryMonth=month;date='';}catch{}}
 async function listBackups(){view='backups';try{backupNames=native?await invoke<string[]>('backups'):[];}catch(e){error=String(e);}}
 async function makeBackup(){try{if(native)await invoke('backup');status='Backup created';await listBackups();}catch(e){error=String(e);}}
 async function restoreBackup(){if(!restoreName||busy)return;busy=true;error='';try{const before=structuredClone(ledger);ledger=await invoke<Ledger>('restore',{name:restoreName});undoStack=[...undoStack,before];confirmRestore=false;status='Backup restored. A backup of the previous data was created.';await listBackups();}catch(e){error=String(e);}finally{busy=false;}}
 function csvText(){return exportRows(filtered,ledger.tags);}
 function toggleSelected(id:string){selectedIds=selectedIds.includes(id)?selectedIds.filter(s=>s!==id):[...selectedIds,id];}
 function selectTag(id:string){const t=ledger.tags.find(t=>t.id===id);if(!t)return;view='tags';filterTags=[t.name];tagIdToManage=id;renameName=t.name;search='';kind='';categoryFilter='';flagged=false;confirmTagRemoval=false;mergeTagsConfirmed=false;}
 async function applyBulk(operation:'add'|'remove'){if(busy)return;try{if(!selectedIds.length||!bulkNames.length)throw new Error('Select transactions and at least one tag');let next=structuredClone(ledger);let ids:string[];if(operation==='add'){const result=resolveTagNames(next,bulkNames);next=result.ledger;ids=result.ids;}else{ids=next.tags.filter(t=>bulkNames.some(n=>tagKey(n)===tagKey(t.name))).map(t=>t.id);if(ids.length!==bulkNames.length)throw new Error('Only existing tags can be removed');}await commit(bulkTags(next,selectedIds,ids,operation),`${operation==='add'?'Added':'Removed'} tags for ${selectedIds.length} selected entries`);bulkNames=[];}catch(e){error=String(e instanceof Error?e.message:e);}}
 async function createTag(){if(busy)return;try{await commit(ensureTag(structuredClone(ledger),newTagName).ledger,'Tag created');newTagName='';}catch(e){error=String(e instanceof Error?e.message:e);}}
 async function saveTagRename(){if(busy)return;try{const target=renameCollision?.id;await commit(renameTag(structuredClone(ledger),tagIdToManage,renameName,mergeTagsConfirmed),'Tag renamed / merged');if(target)selectTag(target);else selectTag(tagIdToManage);}catch(e){error=String(e instanceof Error?e.message:e);}}
 async function deleteTag(){if(busy)return;try{await commit(removeTag(structuredClone(ledger),tagIdToManage),'Tag removed; transactions preserved');tagIdToManage='';renameName='';confirmTagRemoval=false;}catch(e){error=String(e instanceof Error?e.message:e);}}
 async function exportCsv(){try{if(native){status='Exported to '+await invoke<string>('export_csv',{csv:csvText()});}else{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csvText()],{type:'text/csv'}));a.download='expenses.csv';a.click();URL.revokeObjectURL(a.href);}}catch(e){error=String(e);}}
 async function saveCategories(){try{const next={...settings,categories:[...new Set(categoryText.split(',').map(s=>s.trim()).filter(Boolean))]};if(native)await invoke('save_settings',{settings:next});settings=next;settingsOpen=false;status='Categories saved';}catch(e){error=String(e);}}
 function keys(e:KeyboardEvent){if(scannerOpen)return;if((e.ctrlKey||e.metaKey)&&e.key==='d'){e.preventDefault();if(!busy)duplicate();}if((e.ctrlKey||e.metaKey)&&e.key==='z'&&!(e.target instanceof HTMLInputElement||e.target instanceof HTMLTextAreaElement)){e.preventDefault();void undo();}if(e.key==='Escape')clearEntry();if(e.altKey&&e.key==='n'){e.preventDefault();dateInput?.focus();}}
 onMount(async()=>{try{if(native){const data=await invoke<any>('load');ledger=data.ledger;path=data.path;recovery=data.recovery;settings=data.settings;if(data.ocrSelfTest){try{const {ocrSelfTest}=await import('./lib/ocr-self-test');await invoke('finish_ocr_self_test',{result:await ocrSelfTest()});}catch(e){await invoke('finish_ocr_self_test',{result:{passed:false,error:String(e)}});}return;}}else{status='Browser preview · changes last only in this tab';}loaded=true;}catch(e){error=String(e);}});
</script>

<svelte:window onkeydown={keys}/>
<div class="shell">
 <aside>
  <div class="brand"><span class="mark">¥</span><div>Expense Tracker<small>LOCAL · JAPAN</small></div></div>
  <nav aria-label="Main navigation"><button class:active={view==='month'} onclick={()=>view='month'}>▦ &nbsp; Monthly ledger</button><button class:active={view==='history'} onclick={()=>view='history'}>⌕ &nbsp; All history</button><button class:active={view==='tags'} onclick={()=>view='tags'}>◇ &nbsp; Tags & collections</button><button class:active={view==='import'} onclick={()=>view='import'}>↓ &nbsp; Import & reconcile</button><button class:active={view==='backups'} onclick={listBackups}>↺ &nbsp; Backups & restore</button></nav>
  <div class="side-month"><label for="month">Reporting month</label><input id="month" type="month" bind:value={month} onchange={()=>{entryMonth=month;date=month===localDay().slice(0,7)?localDay():'';}}/><div class="month-list">{#each months.slice(0,30) as m}<button class:chosen={m===month} onclick={()=>{month=m;entryMonth=m;date='';}}>{new Date(m+'-01T00:00:00').toLocaleDateString('en-US',{year:'numeric',month:'short'})}<span>{ledger.transactions.filter(t=>t.month===m).length}</span></button>{/each}</div></div>
  <div class="side-bottom"><span class="dot"></span> Offline · JSON storage<button onclick={()=>{categoryText=settings.categories.join(', ');settingsOpen=true;}}>Edit categories</button><small title={path}>{path||'Portable folder / data'}</small></div>
 </aside>
 <main>
  <header><div><p class="eyebrow">YOUR MONEY, AT A GLANCE</p><h1>{view==='month'?new Date(month+'-01T00:00:00').toLocaleDateString('en-US',{year:'numeric',month:'long'}):view==='history'?'All history':view==='tags'?'Tags & collections':view==='import'?'Import & reconciliation':'Backups & restore'}</h1></div><div class="header-actions"><span class="save-status">{busy?'Working…':loaded?'● Saved locally':'Opening…'}</span><button disabled={!undoStack.length||busy} onclick={undo}>Undo <kbd>Ctrl Z</kbd></button></div></header>
  {#if !native}<div class="notice">Browser preview. Use the Windows app for persistent files and backups.</div>{/if}
  {#if recovery}<div class="notice">{recovery}<button onclick={()=>recovery=''}>Dismiss</button></div>{/if}
  {#if error}<div class="error" role="alert">{error}<button onclick={()=>error=''}>Dismiss</button></div>{/if}
  {#if settingsOpen}<section class="card"><h2>Editable categories</h2><label>Separate categories with commas<input class="wide" bind:value={categoryText}/></label><p>Suggestions are optional. Ambiguous descriptions such as “amazon” have no automatic category.</p><button onclick={saveCategories}>Save categories</button><button onclick={()=>settingsOpen=false}>Cancel</button></section>{/if}
  {#if view==='month'||view==='history'||view==='tags'}
   {#if view==='tags'}
    <section class="card tag-manager"><h2>Available tags</h2><div class="tag-list">{#each ledger.tags as tag}<button class:primary={tagIdToManage===tag.id} onclick={()=>selectTag(tag.id)}>{tag.name} <span class="count">{ledger.transactions.filter(t=>t.tagIds.includes(tag.id)).length}</span></button>{/each}{#if !ledger.tags.length}<p>No tags yet. Add tags below or while entering/editing an expense.</p>{/if}</div><div class="tag-create"><input aria-label="New tag name" bind:value={newTagName} placeholder="New tag name" maxlength="120"/><button disabled={busy||!loaded} onclick={createTag}>Create tag</button><button onclick={()=>{filterTags=[];tagIdToManage='';}}>Show all transactions</button></div>
     {#if managedTag}<div class="manage"><h3>Manage “{managedTag.name}”</h3><label>Rename tag<input bind:value={renameName} maxlength="120"/></label>{#if renameCollision}<label class="check"><input type="checkbox" bind:checked={mergeTagsConfirmed}/>Merge membership into “{renameCollision.name}” without duplicates</label>{/if}<button disabled={busy||!!renameCollision&&!mergeTagsConfirmed} onclick={saveTagRename}>{renameCollision?'Merge tags':'Rename tag'}</button><button disabled={busy} onclick={()=>confirmTagRemoval=true}>Remove tag…</button>{#if confirmTagRemoval}<div class="notice">Remove this tag and its associations? Transactions and amounts remain intact.<button disabled={busy} onclick={deleteTag}>Remove tag</button><button onclick={()=>confirmTagRemoval=false}>Cancel</button></div>{/if}</div>{/if}
    </section>
    <section class="stats"><div><span>Expenses</span><strong>{money(spending.expenses)}</strong></div><div><span>Refunds / reimbursements</span><strong>{money(spending.refunds)}</strong></div><div class="highlight"><span>Net spending · expenses − refunds</span><strong>{money(spending.netSpending)}</strong></div><div><span>Other income / salary</span><strong>{money(spending.income+spending.salary)}</strong><small>Income {money(spending.income)} · salary {money(spending.salary)}</small></div></section><p>{filtered.length} matching entries · {spending.unresolved} unresolved amounts excluded{spending.unresolved?' — totals are incomplete':''}. Each matching transaction counts once.</p>
   {:else}
   <section class="stats"><div><span>Salary</span><strong>{money(summary.salary)}</strong></div><div><span>Expenses</span><strong>{money(summary.expenses)}</strong></div><div><span>Other income & refunds</span><strong>{money(summary.income+summary.refunds)}</strong></div><div class="highlight"><span>Monthly {summary.savings<0?'deficit':'surplus'}</span><strong class:negative={summary.savings<0}>{money(summary.savings)}</strong></div></section>
   <div class="savings-line"><span>Accumulated savings through {month} <b class:negative={accumulated.savings<0}>{money(accumulated.savings)}</b></span><small>{accumulated.unresolved?`${accumulated.unresolved} unresolved amounts excluded · `:''}Salary + income + refunds − expenses</small></div>
   <section class="entry card"><div class="section-title"><h2>{editing?'Edit entry':'Quick entry'}</h2><button disabled={busy||!loaded} onclick={()=>scannerOpen=true}>Scan receipt</button><small>Alt N to focus · Ctrl D to duplicate last · Escape to clear</small></div>
    <form onsubmit={(e)=>{e.preventDefault();void submit();}}><div class="entry-primary"><label>Date <span>optional</span><input aria-label="Transaction date" type="date" bind:value={date} bind:this={dateInput}/></label><label class="grow">Description<input aria-label="Description" placeholder="What was it for?" bind:value={description} bind:this={descInput} list="descriptions" autocomplete="off"/></label><label>Amount / calculation<input aria-label="Amount" class="amount-input" placeholder="e.g. 15470/4" bind:value={amount} autocomplete="off"/><small>{amountPreview||'Blank = unresolved'}</small></label><button class="primary add" disabled={busy||!loaded} type="submit">{editing?'Save changes':'Add entry'} ↵</button></div>
     <div class="entry-details"><label>Type<select bind:value={type}><option value="expense">Expense</option><option value="salary">Salary</option><option value="income">Other income</option><option value="refund">Refund / reimbursement</option></select></label><label>Report in<input aria-label="Entry reporting month" type="month" bind:value={entryMonth}/></label><label>Category<input bind:value={category} list="categories" placeholder={suggestion?`Suggest: ${suggestion}`:'Uncategorized'}/></label>{#if suggestion&&!category}<button type="button" class="link" onclick={()=>category=suggestion}>Use {suggestion}</button>{/if}<label class="grow">Notes<input bind:value={notes} placeholder="Historical notes or context"/></label>{#if editing}<button type="button" onclick={clearEntry}>Cancel</button>{/if}</div>
     <TagSelector tags={ledger.tags} bind:names={entryTags} disabled={busy}/>
     <small class="entry-help">Amounts are whole yen, halves away from zero. Negative expense input becomes income. Type controls direction; blank dates stay undated.</small>
    </form>
    {#if editing}{@const source=ledger.transactions.find(t=>t.id===editing)?.source}{#if source}<details><summary>Original import · Sheet1!{source.cell}</summary><pre>{JSON.stringify(source,null,2)}</pre></details>{/if}{/if}
   </section>
   {#if view==='month'&&suggestions.length}<div class="recurring"><span>Recurring suggestions · review before adding</span>{#each suggestions as t}<button disabled={busy} onclick={()=>duplicate(t)}>{t.description} · {money(t.amount||0)} ＋</button>{/each}</div>{/if}
   {#if !ledger.transactions.length}<section class="empty card"><h2>Start with your existing expenses</h2><p>Review the 28 months in your workbook, including undated entries and reconciliation differences, before importing.</p><button class="primary" disabled={busy} onclick={bundled}>Preview Japan expenses.xlsx</button><button disabled={busy} onclick={()=>fileInput.click()}>Choose workbook…</button></section>{/if}
   {/if}
   <section class="card ledger"><div class="section-title"><h2>{view==='history'?'History':'Transactions'} <span class="count">{filtered.length}</span></h2><button onclick={exportCsv} disabled={busy}>Export filtered CSV</button></div><div class="filters"><input aria-label="Search history" class="grow" placeholder="Search descriptions, notes, source cells…" bind:value={search}/><select aria-label="Filter type" bind:value={kind}><option value="">All types</option><option value="expense">Expenses</option><option value="salary">Salary</option><option value="income">Other income</option><option value="refund">Refunds</option></select><select aria-label="Filter category" bind:value={categoryFilter}><option value="">All categories</option>{#each categories as c}<option>{c}</option>{/each}</select><label class="check"><input type="checkbox" bind:checked={flagged}/>Flagged</label></div>
    <TagSelector tags={ledger.tags} bind:names={filterTags} label="Filter tags" allowCreate={false}/><label class="tag-mode">Tag matching<select bind:value={tagMode}><option value="any">Match ANY selected tag (default)</option><option value="all">Match ALL selected tags</option></select></label>
    <div class="bulk-controls"><button disabled={busy} onclick={()=>selectedIds=[...new Set([...selectedIds,...filtered.slice(0,500).map(t=>t.id)])]}>Select visible entries (up to 500)</button><button onclick={()=>selectedIds=[]}>Clear selection</button><small>{selectedIds.length} explicitly selected across filters</small>{#if selectedIds.length}<TagSelector tags={ledger.tags} bind:names={bulkNames} label="Bulk tags" disabled={busy}/><button disabled={busy} onclick={()=>applyBulk('add')}>Add tags to selected</button><button disabled={busy} onclick={()=>applyBulk('remove')}>Remove tags from selected</button>{/if}</div>
    <div class="table-scroll"><table><thead><tr><th>Select</th><th>Date / month</th><th>Description</th><th>Type / category</th><th class="right">Amount</th><th class="right">Actions</th></tr></thead><tbody>{#each filtered.slice(0,500) as t (t.id)}<tr><td><input type="checkbox" aria-label={`Select ${t.description} ${t.id}`} checked={selectedIds.includes(t.id)} disabled={busy} onchange={()=>toggleSelected(t.id)}/></td><td class="date-cell">{t.date||'Undated'}<small>{t.month}</small></td><td><b>{t.description}</b>{#each tagNames(ledger.tags,t.tagIds) as name}<span class="badge">{name}</span>{/each}{#if t.receipt}<small class="source">Reviewed receipt · {t.receipt.input}</small>{/if}{#if t.notes}<small>{t.notes}</small>{/if}{#if t.flags.length}<small class="flags" title={t.flags.join(' · ')}>⚑ {t.flags.join(' · ')}</small>{/if}{#if t.source}<small class="source">Sheet1!{t.source.cell}</small>{/if}</td><td>{t.type}<small>{t.category||'Uncategorized'}</small></td><td class="right numeric" class:income={t.type!=='expense'}>{t.amount===null?'Unresolved':money(t.amount)}</td><td class="right actions"><button aria-label={`Edit ${t.description}`} disabled={busy} onclick={()=>edit(t)}>Edit</button><button title="Duplicate into entry form" disabled={busy} onclick={()=>duplicate(t)}>＋</button><button class="delete" title="Delete entry (Undo available)" aria-label={`Delete ${t.description}`} disabled={busy} onclick={()=>remove(t)}>×</button></td></tr>{/each}</tbody></table>{#if !filtered.length}<div class="no-results">No entries to show.</div>{/if}</div>
    <div class="table-footer"><span>{filtered.length>500?'Showing first 500 matches. Narrow your search.':`${filtered.length} entries`} · {filteredTotals.unresolved} unresolved</span><span>Filtered net <b>{money(filteredTotals.savings)}</b></span></div>
   </section>
  {:else if view==='import'}
   <section class="card"><div class="section-title"><div><h2>Review before importing</h2><p>Original dates, descriptions, calculations, and notes remain attached to every entry. Reporting months stay with the workbook blocks.</p></div><div><button disabled={busy} onclick={bundled}>Preview included workbook</button><button class="primary" disabled={busy} onclick={()=>fileInput.click()}>Choose .xlsx</button></div></div></section>
   {#if pending&&plan}<section class="card"><div class="section-title"><div><h2>{pending.report.file}</h2><p>{pending.report.counts.amounts} amount entries + {pending.report.counts.missing} unresolved + 28 salaries · {pending.report.counts.undated} undated · {pending.report.counts.yearErrors} likely year errors</p></div><button class="primary" disabled={busy||!plan.fresh.length} onclick={importNow}>Import {plan.fresh.length} new entries</button></div><p>{plan.skipped.length} existing or previously deleted entries skipped. {plan.conflicts.length} source changes require review; existing entries are preserved.</p>{#if plan.conflicts.length}<details><summary>Changed source cells — review against existing entries</summary>{#each plan.conflicts as t}<p>Sheet1!{t.source?.cell}: {t.description} ({t.source?.originalValue}). Existing entry is unchanged. Edit it manually if needed.</p>{/each}</details>{/if}<div class="notice">Income/refund labels on negative entries are provisional and editable. No dates are corrected automatically. “Pay to…” notes have no accounting effect. ICOCA top-ups count as expenses.</div></section>
    <section class="card"><h2>Monthly reconciliation</h2><p>Workbook expense subtotals are net of negative entries, except September 2025. “Raw net” converts to your savings convention. “Δ rounding” is rounded net minus exact net. No unresolved amount is treated as zero.</p><div class="table-scroll"><table class="reconciliation"><thead><tr><th>Month / source</th><th class="right">Salary</th><th class="right">WB subtotal</th><th class="right">Adjustment</th><th class="right">Raw net</th><th class="right">Rounded net</th><th class="right">Δ rounding</th><th class="right">Unexplained</th></tr></thead><tbody>{#each pending.report.months as r}<tr><td>{r.month}<small title={r.subtotalFormula}>{r.subtotalCell} · {r.count} entries{r.unresolved?` · ${r.unresolved} unresolved`:''}</small></td><td class="right">{fmt(r.salary)}</td><td class="right" title={r.subtotalFormula}>{r.workbookSubtotal}</td><td class="right">{r.subtotalAdjustment}</td><td class="right">{r.workbookNet}</td><td class="right">{fmt(r.savings)}</td><td class="right">{Number(r.roundingDelta).toFixed(6).replace(/\.?0+$/,'')||'0'}</td><td class="right" class:flags={Math.abs(Number(r.unexplained))>0.001}>{Math.abs(Number(r.unexplained))<0.001?'0*':r.unexplained}</td></tr>{/each}</tbody></table></div><small>* Differences under ¥0.001 are workbook cached-value precision; full differences are retained in the report.</small><p>For the exceptional month, omitted reimbursements are included in the reconciliation adjustment shown above. Exact amounts use the source calculations; per-entry rounding changes June and August 2026 totals. Unresolved entries leave totals incomplete.</p><details><summary>Workbook monthly balance formulas and full reconciliation metadata</summary><pre>{JSON.stringify(pending.report,null,2)}</pre></details></section>
    <section class="card"><div class="section-title"><h2>Entry preview <span class="count">{previewRows.length}</span></h2><div class="filters"><input aria-label="Search import preview" placeholder="Search preview…" bind:value={previewSearch}/><select aria-label="Preview filter" bind:value={previewFilter}><option value="flagged">Flagged entries</option><option value="all">All entries</option><option value="missing">Missing amounts</option><option value="year">Likely year errors</option></select></div></div><div class="table-scroll"><table><thead><tr><th>Source</th><th>Date / month</th><th>Description</th><th class="right">Original → rounded</th><th>Flags</th></tr></thead><tbody>{#each previewRows.slice(0,350) as t}<tr><td><details><summary>{t.source?.cell}</summary><pre>{JSON.stringify(t.source,null,2)}</pre></details></td><td>{t.date||'Undated'}<small>Report: {t.month}</small></td><td>{t.description}<small>{t.notes}</small></td><td class="right" title={t.source?.amount.formula||''}>{t.source?.originalValue??'Missing'} → {t.amount===null?'Unresolved':fmt(t.amount)}</td><td class="flags">{t.flags.join(' · ')}</td></tr>{/each}</tbody></table></div><small>Showing up to 350 rows. Search or filter for more. All rows are included in the import.</small></section>
   {:else}<section class="empty card"><h2>Your workbook stays untouched</h2><p>Choose the workbook to inspect all 28 monthly blocks and verify their accounting before importing.</p></section>{/if}
  {:else}
   <section class="card"><div class="section-title"><div><h2>Automatic backups</h2><p>A dated snapshot is written before every ledger save and restore. Restores also support Undo during this session.</p></div><button disabled={busy} onclick={makeBackup}>Back up now</button></div><p class="path">{path}/backups</p>{#if !native}<p>Backups require the Windows app.</p>{/if}<div class="backup-controls"><select aria-label="Backup to restore" bind:value={restoreName}><option value="">Choose a backup ({backupNames.length})</option>{#each backupNames as name}<option value={name}>{name}</option>{/each}</select><button disabled={!restoreName||busy} onclick={()=>confirmRestore=true}>Restore…</button></div>{#if confirmRestore}<div class="notice">Replace current entries with {restoreName}? Current data will be backed up first.<button disabled={busy} onclick={restoreBackup}>Restore this backup</button><button onclick={()=>confirmRestore=false}>Cancel</button></div>{/if}<p>Keep the entire ExpenseTracker folder together. Copy it elsewhere periodically for protection against disk failure. Backups are retained until you remove them yourself.</p></section>
   {#if ledger.imports.length}<section class="card"><h2>Saved import reports</h2>{#each ledger.imports as report}<details><summary>{report.file} · {report.generatedAt.slice(0,10)} · {report.counts.amounts} entries</summary><pre>{JSON.stringify(report,null,2)}</pre></details>{/each}</section>{/if}
  {/if}
  <footer role="status">{status||'Ready. Entries save automatically.'}</footer>
 </main>
</div>
{#if scannerOpen}<ReceiptScanner {categories} tags={ledger.tags} transactions={ledger.transactions} onclose={()=>scannerOpen=false} onconfirm={saveReceipt}/>{/if}
<input type="file" accept=".xlsx" bind:this={fileInput} onchange={pickFile} hidden/>
<datalist id="descriptions">{#each descriptions as d}<option value={d}></option>{/each}</datalist><datalist id="categories">{#each categories as c}<option value={c}></option>{/each}</datalist>

